using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using Random=UnityEngine.Random;
namespace Underwater.Editor {
public static class OuterSeabedDress {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Folder="Assets/UnderwaterArt/OuterSeabed/";
 static List<MeshCollider> ground;
 static Dictionary<Mesh,Mesh> distance=new Dictionary<Mesh,Mesh>();
 public static void Audit(){
  EditorSceneManager.OpenScene(Scene);var root=GameObject.Find("Outer seabed rock gardens");if(!root)throw new Exception("Missing clustered reef");var groups=root.GetComponentsInChildren<LODGroup>();long near=0,far=0;var used=new HashSet<string>();foreach(var f in root.GetComponentsInChildren<MeshFilter>())used.Add(AssetDatabase.GetAssetPath(f.sharedMesh));int rocks=0,plants=0;
  foreach(var group in groups){var levels=group.GetLODs();if(levels.Length==2){rocks++;long high=levels[0].renderers.Sum(r=>(long)r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3);long low=levels[1].renderers.Sum(r=>(long)r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3);if(low>=high)throw new Exception("Rock LOD did not reduce geometry");near+=high;far+=low;}else plants++;foreach(var r in group.GetComponentsInChildren<MeshRenderer>())if(r.shadowCastingMode!=ShadowCastingMode.Off||!r.sharedMaterial)throw new Exception("Render setup invalid");}
  var cam=Camera.main;cam.fieldOfView=90;cam.aspect=1;cam.farClipPlane=65;long maxTriangles=0;int maxRenderers=0;foreach(var center in OceanWorld.Centers)for(int yaw=0;yaw<360;yaw+=45){cam.transform.position=center+Vector3.up*1.6f;cam.transform.rotation=Quaternion.Euler(12,yaw,0);var planes=GeometryUtility.CalculateFrustumPlanes(cam);long tris=0;int renderers=0;foreach(var r in root.GetComponentsInChildren<MeshRenderer>())if(GeometryUtility.TestPlanesAABB(planes,r.bounds)){tris+=r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3;renderers++;}maxTriangles=Math.Max(maxTriangles,tris);maxRenderers=Math.Max(maxRenderers,renderers);}
  // Remove only obsolete assets generated by this dressing pass.
  foreach(var path in AssetDatabase.FindAssets("t:Mesh",new[]{Folder.TrimEnd('/')} ).Select(AssetDatabase.GUIDToAssetPath))if(!used.Contains(path)&&!Path.GetFileName(path).StartsWith("Shared"))AssetDatabase.DeleteAsset(path);
  AssetDatabase.SaveAssets();Directory.CreateDirectory("Renders/OuterSeabed");File.WriteAllLines("Renders/OuterSeabed/UsedAssets.txt",used);File.WriteAllText("Renders/OuterSeabed/Performance.txt","Rock patches="+rocks+" Plant patches="+plants+"\nTotal rock high triangles="+near+" distant="+far+"\n64 habitat views, 65m far clip: conservative visible added geometry upper bound (counts BOTH rock LODs)="+maxTriangles+" triangles, "+maxRenderers+" renderers.\nNo added lights, rigidbodies, per-frame scripts or shadows. Plants cull before rocks. Static simplified rock colliders.\nThis is an editor geometry audit, not measured Quest FPS.\n");RealisticReefBuilder.ValidateScene();ReefCollisionValidation.Run();Debug.Log("NATURAL_CLUSTER_AUDIT_PASSED near="+near+" far="+far+" maxVisible="+maxTriangles);
 }
 static float Floor(float x,float z){float y=float.NegativeInfinity;var ray=new Ray(new Vector3(x,45,z),Vector3.down);foreach(var c in ground)if(c.Raycast(ray,out var h,200))y=Mathf.Max(y,h.point.y);return y;}
 static Mesh Save(Mesh m,string name){string path=Folder+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(m,path);return m;}
 static void Batch(List<CombineInstance> parts,string name,Material mat,Transform parent,bool solid){if(parts.Count==0)return;var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.CombineMeshes(parts.ToArray(),true,true);m=Save(m,name);var go=new GameObject(name);go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>().sharedMesh=m;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;var lod=go.AddComponent<LODGroup>();if(solid){var lowParts=parts.Select(p=>new CombineInstance{mesh=distance[p.mesh],transform=p.transform}).ToArray();var low=new Mesh{name=name+" distance",indexFormat=IndexFormat.UInt32};low.CombineMeshes(lowParts,true,true);low=Save(low,name+"_Distance");var child=new GameObject("Distance geometry");child.transform.SetParent(go.transform,false);child.AddComponent<MeshFilter>().sharedMesh=low;var lr=child.AddComponent<MeshRenderer>();lr.sharedMaterial=mat;lr.shadowCastingMode=ShadowCastingMode.Off;lr.receiveShadows=false;lr.lightProbeUsage=LightProbeUsage.Off;lr.reflectionProbeUsage=ReflectionProbeUsage.Off;go.layer=8;go.AddComponent<MeshCollider>().sharedMesh=low;lod.SetLODs(new[]{new LOD(.24f,new[]{r}),new LOD(.065f,new[]{lr})});}else lod.SetLODs(new[]{new LOD(.16f,new[]{r})});lod.RecalculateBounds();}
 public static void Run(){
  var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var previous=GameObject.Find("Outer seabed rock gardens");if(previous)UnityEngine.Object.DestroyImmediate(previous);var root=new GameObject("Outer seabed rock gardens");
  var temp=new GameObject("Temporary saved sand probes");ground=new List<MeshCollider>();foreach(var f in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None).Where(f=>f.name.StartsWith("Continuous seabed")||f.name.EndsWith("stitched sand"))){var go=new GameObject(f.name);go.transform.SetParent(temp.transform);go.transform.SetPositionAndRotation(f.transform.position,f.transform.rotation);go.transform.localScale=f.transform.lossyScale;go.AddComponent<MeshFilter>().sharedMesh=f.sharedMesh;ground.Add(go.AddComponent<MeshCollider>());ground[ground.Count-1].sharedMesh=f.sharedMesh;}
  Physics.SyncTransforms();Random.InitState(914772);var rocks=Enumerable.Range(0,3).Select(i=>AssetDatabase.LoadAssetAtPath<Mesh>("Assets/UnderwaterArt/GapFill/Limestone"+i+".asset")).ToArray();var grass=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/UnderwaterArt/Meshes/Seagrass_1.asset");var rockMat=AssetDatabase.LoadAssetAtPath<Material>("Assets/UnderwaterArt/Materials/02 Encrusted limestone.mat");var grassMat=AssetDatabase.LoadAssetAtPath<Material>("Assets/UnderwaterArt/Materials/10 Seagrass.mat");
  distance.Clear();for(int i=0;i<3;i++){var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/UnderwaterArt/Meshes/Limestone_"+i+".asset");rocks[i]=Save(FishDistanceMesh.Create(source,14),"SharedRock"+i);distance[rocks[i]]=Save(FishDistanceMesh.Create(source,5),"SharedRockLow"+i);}
  var vegetation=new ReefGeometry();for(int k=0;k<7;k++){float angle=k*2.39996f;var side=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*.035f;var start=new Vector3(Mathf.Sin(angle)*.2f,0,Mathf.Cos(angle)*.2f);int first=0;for(int j=0;j<4;j++){float f=j/3f;var p=start+new Vector3(Mathf.Sin(angle)*f*f*.25f,f*(.5f+k*.04f),Mathf.Cos(angle)*f*f*.25f);int index=vegetation.Vertex(p-side*(1-f*.9f),new Vector2(0,f),Color.white);vegetation.Vertex(p+side*(1-f*.9f),new Vector2(1,f),Color.white);if(j==0)first=index;else vegetation.Quad(first+(j-1)*2,first+(j-1)*2+1,index+1,index);}}grass=Save(vegetation.Mesh("Distant seagrass seven blades"),"SharedGrass");
  var obstacles=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name=="Porous reef outcrop"||r.name.Contains("ship on")||r.GetComponent<SeaLife>()||r.GetComponent<TeleportShell>()).Select(r=>r.bounds).ToArray();int count=0,plants=0;var centers=new List<Vector2>();
  for(int tx=-9;tx<9;tx++)for(int tz=-8;tz<20;tz++){
   // Cells only name spatial batches. Widely jittered centres, broad empty
   // sand pockets and mixed island sizes prevent visible rows of equal rocks.
   float field=Mathf.PerlinNoise(tx*.43f+18.7f,tz*.43f+39.4f);if(field<.53f||Mathf.PerlinNoise(tx*.19f+7.4f,tz*.19f+22.6f)<.36f)continue;
   float cx=tx*20+Random.Range(1f,19f),cz=tz*20+Random.Range(1f,19f);var center=new Vector2(cx,cz);if(centers.Any(c=>(c-center).sqrMagnitude<18*18))continue;centers.Add(center);
   bool dense=field>.66f;int population=dense?Random.Range(6,10):Random.Range(2,5);float spread=dense?Random.Range(3.5f,6f):Random.Range(4f,8f);float islandScale=Random.Range(.65f,1.25f);
   var stone=new List<CombineInstance>();var blades=new List<CombineInstance>();
   for(int n=0;n<population;n++){
    var offset=Random.insideUnitCircle*spread;float x=cx+offset.x,z=cz+offset.y;float y=Floor(x,z);if(float.IsInfinity(y))continue;
    if(z>-28&&z<275&&Mathf.Abs(x-Mathf.Sin(z*.115f)*2)<2.8f)continue;
    var p=new Vector3(x,y,z);if(Mathf.Abs(x)<30&&z>-28&&z<275&&obstacles.Any(b=>{var q=b.ClosestPoint(p);return new Vector2(q.x-x,q.z-z).sqrMagnitude<9;}))continue;
    float radius=(n==0?Random.Range(1.8f,3.3f):Random.Range(.35f,1.65f))*islandScale;var scale=new Vector3(radius,radius*Random.Range(.25f,.65f),radius*Random.Range(.65f,1.5f));var rot=Quaternion.Euler(Random.Range(-12f,12f),Random.Range(0,360),Random.Range(-10f,10f));var mesh=rocks[count%3];float lift=float.NegativeInfinity;
    foreach(var v in mesh.vertices){var w=rot*Vector3.Scale(v,scale)+p;float floor=Floor(w.x,w.z);if(!float.IsInfinity(floor))lift=Mathf.Max(lift,floor-w.y);}p.y+=lift-.12f;stone.Add(new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(p,rot,scale)});count++;
    for(int j=0;j<(dense?2:1);j++){float a=Random.value*6.283f;float px=x+Mathf.Cos(a)*(radius+.5f),pz=z+Mathf.Sin(a)*(radius+.5f),py=Floor(px,pz);if(float.IsInfinity(py))continue;blades.Add(new CombineInstance{mesh=grass,transform=Matrix4x4.TRS(new Vector3(px,py-.03f,pz),Quaternion.Euler(0,Random.Range(0,360),0),Vector3.one*Random.Range(.8f,1.5f))});plants++;}
   }
   Batch(stone,"Rocks_"+tx+"_"+tz,rockMat,root.transform,true);Batch(blades,"Plants_"+tx+"_"+tz,grassMat,root.transform,false);
  }
  UnityEngine.Object.DestroyImmediate(temp);Physics.SyncTransforms();AssetDatabase.SaveAssets();RealisticReefBuilder.ValidateScene();ReefCollisionValidation.Run();EditorSceneManager.SaveScene(scene);Directory.CreateDirectory("Renders/OuterSeabed");File.WriteAllText("Renders/OuterSeabed/Validation.txt","Rocks="+count+" Plants="+plants+"\n20m spatial batches, saved sand grounding including all four extensions.\n");
  var cam=Camera.main;var optics=cam.GetComponent<ReefOptics>();if(optics)optics.enabled=false;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.02f,.25f,.38f);cam.farClipPlane=180;cam.fieldOfView=75;cam.transform.position=new Vector3(0,20,-15);cam.transform.LookAt(new Vector3(0,-1,-70));ReefCorrectionAudit.Capture(cam,"Renders/OuterSeabed/WideSouth.png");cam.transform.position=new Vector3(28,16,10);cam.transform.LookAt(new Vector3(85,0,30));ReefCorrectionAudit.Capture(cam,"Renders/OuterSeabed/WideEast.png");Debug.Log("OUTER_SEABED_DRESSED rocks="+count+" plants="+plants);
 }
}
}
